from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SPYCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        spy_security = self.AddEquity(
            "SPY",
            Resolution.Minute,
            Market.USA,
            True,
            1.0,
            False
        )
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option = self.AddOption("SPY", Resolution.Minute, Market.USA, True)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_symbol = option.Symbol

        self.fast_window = RollingWindow[float](5)
        self.slow_window = RollingWindow[float](20)

        self._aggregate_date = None
        self._aggregate_end = None
        self._aggregate_closes = []
        self._aggregate_expected_end = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._handle_unexpected_spy_position()
        self._handle_held_position_exits(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        consolidated_close, consolidated_end = self._consolidate_minute_bar(spy_bar)
        if consolidated_close is None:
            return

        previous_fast = self.fast_window[0] if self.fast_window.IsReady else None
        previous_slow = self.slow_window[0] if self.slow_window.IsReady else None

        self.fast_window.Add(consolidated_close)
        self.slow_window.Add(consolidated_close)

        if not self.fast_window.IsReady or not self.slow_window.IsReady:
            return

        current_fast = sum(self.fast_window[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow_window[i] for i in range(20)) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        if self.held_symbol is not None or self._entry_order_is_open():
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if not (
            time(9, 45) <= consolidated_end.time() <= time(14, 30)
        ):
            return

        if previous_fast > previous_slow:
            return

        if current_fast <= current_slow:
            return

        self._enter_call(slice, consolidated_close)

    def _consolidate_minute_bar(self, minute_bar):
        local_end = minute_bar.EndTime
        current_date = local_end.date()
        current_minute = local_end.minute

        if self._aggregate_date != current_date:
            self._reset_aggregate()
            self._aggregate_date = current_date

        if not (time(9, 30) <= local_end.time() <= time(16, 0)):
            return None, None

        starts_bucket = current_minute % 5 == 1

        if starts_bucket:
            self._aggregate_closes = [float(minute_bar.Close)]
            self._aggregate_end = local_end + timedelta(minutes=4)
            self._aggregate_expected_end = local_end + timedelta(minutes=1)
            return None, None

        if not self._aggregate_closes:
            return None, None

        if local_end != self._aggregate_expected_end:
            self._reset_aggregate()
            return None, None

        self._aggregate_closes.append(float(minute_bar.Close))
        self._aggregate_expected_end = local_end + timedelta(minutes=1)

        if len(self._aggregate_closes) < 5:
            return None, None

        close = self._aggregate_closes[-1]
        end_time = self._aggregate_end
        self._reset_aggregate()
        return close, end_time

    def _reset_aggregate(self):
        self._aggregate_closes = []
        self._aggregate_end = None
        self._aggregate_expected_end = None

    def _enter_call(self, slice: Slice, spy_price: float):
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        eligible_contracts = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    eligible_contracts.append(contract)

        if not eligible_contracts:
            self.Debug("Skipped entry: no expiration satisfies the rule.")
            return

        nearest_expiry = min(
            contract.Expiry.date() for contract in eligible_contracts
        )

        strike_floor = spy_price * 1.01
        candidates = [
            contract for contract in eligible_contracts
            if (
                contract.Expiry.date() == nearest_expiry
                and contract.Strike >= strike_floor
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}.".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def _handle_held_position_exits(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        if current_date >= expiry_date:
            self.blocked_entry_date = current_date
            self._submit_exit("expiration processing")
            return

        preceding_trading_date = self._preceding_trading_date(expiry_date)

        if (
            current_date == preceding_trading_date
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        bid = None
        ask = None

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(self.held_symbol)
            if contract is not None:
                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)
                break

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled,
            ):
                self.exit_ticket.Cancel("Replacing exit order.")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {}.".format(reason))

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def _preceding_trading_date(self, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def _handle_unexpected_spy_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Invested:
            self.blocked_entry_date = self.Time.date()
            self.Debug("Unexpected SPY exercise or assignment; liquidating SPY.")
            self.MarketOrder(self.spy, -holding.Quantity)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: {} at {:.4f}.".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}.".format(
                        order_event.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                if not self.Portfolio[order_event.Symbol].Invested:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.exit_ticket = None

