        close_price, bar_end_time = completed_bar

        previous_fast = self._sma(self.fast_closes)
        previous_slow = self._sma(self.slow_closes)

        self.fast_closes.append(close_price)
        self.slow_closes.append(close_price)

        current_fast = self._sma(self.fast_closes)
        current_slow = self._sma(self.slow_closes)

        if (
            previous_fast is None
            or previous_slow is None
            or current_fast is None
            or current_slow is None
        ):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            (bar_end_time.hour > 9 or
             (bar_end_time.hour == 9 and bar_end_time.minute >= 45))
            and
            (bar_end_time.hour < 14 or
             (bar_end_time.hour == 14 and bar_end_time.minute <= 30))
        )

        if bullish_cross and eligible_time:
            self._try_enter(data, current_date, close_price)

    def _update_five_minute_bar(self, close_price, local_time):
        if local_time.weekday() >= 5:
            return None

        hour = local_time.hour
        minute = local_time.minute

        if hour < 9 or hour > 15:
            return None

        if hour == 9 and minute < 31:
            return None

        if hour == 15 and minute > 60:
            return None

        minutes_since_first_close = (hour * 60 + minute) - (9 * 60 + 31)
        end_minute_absolute = 9 * 60 + 35 + (minutes_since_first_close // 5) * 5
        end_hour, end_minute = divmod(end_minute_absolute, 60)
        bucket_end_minute = end_hour * 60 + end_minute

        bucket_key = (local_time.date(), bucket_end_minute)

        if self.bucket_date is None or (
            self.bucket_date,
            self.bucket_end_minute
        ) != bucket_key:
            completed = self._finish_bucket()

            self.bucket_date = local_time.date()
            self.bucket_end_minute = bucket_end_minute
            self.bucket_expected_minute = bucket_end_minute - 4
            self.bucket_closes = []
            self.bucket_valid = (
                (hour * 60 + minute) == self.bucket_expected_minute
            )

            self.bucket_closes.append(close_price)
            self.bucket_expected_minute += 1

            if (hour * 60 + minute) == bucket_end_minute:
                self.bucket_valid = (
                    self.bucket_valid and len(self.bucket_closes) == 5
                )
                result = self._finish_bucket()
                return result if result is not None else completed

            return completed

        if (hour * 60 + minute) != self.bucket_expected_minute:
            self.bucket_valid = False

        self.bucket_closes.append(close_price)
        self.bucket_expected_minute += 1

        if (hour * 60 + minute) == bucket_end_minute:
            return self._finish_bucket()

        return None

    def _finish_bucket(self):
        if self.bucket_date is None:
            return None

        result = None

        if self.bucket_valid and len(self.bucket_closes) == 5:
            result = (
                self.bucket_closes[-1],
                self.Time.replace(
                    hour=self.bucket_end_minute // 60,
                    minute=self.bucket_end_minute % 60,
                    second=0,
                    microsecond=0
                )
            )

        self.bucket_date = None
        self.bucket_end_minute = None
        self.bucket_expected_minute = None
        self.bucket_closes = []
        self.bucket_valid = True

        return result

    @staticmethod
    def _sma(values):
        if not values:
            return None
        if len(values) < values.maxlen:
            return None
        return sum(values) / len(values)

    def _try_enter(self, data, current_date, spy_price):
        if self.expiry_blocked_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_order_id is not None:
            return

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price")
            return

        chain = None
        for candidate_chain in data.OptionChains.Values:
            chain = candidate_chain
