from datetime import timedelta
from collections import deque


class SpyLongCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 730)
        )

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)

        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_key = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None

        self.no_entry_today = False
        self.last_date = None

    def OnData(self, slice):
        today = self.Time.date()

        if self.last_date != today:
            self.last_date = today
            self.no_entry_today = False

        self._handle_unexpected_equity_position()
        self._handle_expiration_processing()

        spy_bar = slice.Bars[self.spy.Symbol] if slice.Bars.ContainsKey(self.spy.Symbol) else None
        if spy_bar is not None:
            completed_bar = self._add_minute_to_five_minute_bar(spy_bar)
            if completed_bar is not None:
                self._process_completed_bar(completed_bar, slice)

        self._evaluate_profit_target(slice)
        self._evaluate_time_stop()

    def _add_minute_to_five_minute_bar(self, minute_bar):
        end_time = minute_bar.EndTime
        end_minute = end_time.hour * 60 + end_time.minute

        # Regular-session minute bars ending from 09:31 through 16:00.
        if end_minute < 571 or end_minute > 960:
            return None

        bucket_end_minute = 575 + ((end_minute - 571) // 5) * 5
        bucket_key = (end_time.date(), bucket_end_minute)

        if self.current_bucket_key is None:
            self.current_bucket_key = bucket_key
        elif bucket_key != self.current_bucket_key:
            completed = self._finish_bucket()
            self.current_bucket_key = bucket_key
            self.current_bucket_bars = {
                end_time: minute_bar
            }
            return completed

        self.current_bucket_bars[end_time] = minute_bar

        if end_minute == bucket_end_minute:
            return self._finish_bucket()

        return None

    def _finish_bucket(self):
        bars = self.current_bucket_bars
        self.current_bucket_bars = {}

        # Do not synthesize an incomplete five-minute bar.
        if len(bars) != 5:
            return None

        ordered = [bars[key] for key in sorted(bars)]
        first = ordered[0]
        last = ordered[-1]

        return TradeBar(
            last.EndTime,
            self.spy.Symbol,
            first.Open,
            max(bar.High for bar in ordered),
            min(bar.Low for bar in ordered),
            last.Close,
            sum(bar.Volume for bar in ordered),
            last.Period
        )

    def _process_completed_bar(self, bar, slice):
        self.fast_closes.append(float(bar.Close))
        self.slow_closes.append(float(bar.Close))

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        fast = sum(self.fast_closes) / 5.0
        slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_time = bar.EndTime.time()
        if not (
            bullish_cross
            and bar_time >= time(9, 45)
            and bar_time <= time(14, 30)
        ):
            return

        self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice, spy_price):
        if self.no_entry_today:
            return

        if self.held_symbol is not None and self.Portfolio[self.held_symbol].Quantity > 0:
            return

        if self._ticket_is_open(self.entry_ticket):
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain.Contracts.Values:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover"
        )

    def _evaluate_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.Portfolio[self.held_symbol].Quantity <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            return

        if not slice.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self):
        if self.held_symbol is None:
            return

        if self.Portfolio[self.held_symbol].Quantity <= 0:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_trading_day = expiry - timedelta(days=1)

        while not self.Securities[self.spy.Symbol].Exchange.Hours.IsDateOpen(
            previous_trading_day
        ):
            previous_trading_day -= timedelta(days=1)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration-eve time stop")

    def _handle_expiration_processing(self):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if self.Time.date() >= expiry:
            self.no_entry_today = True
            self._submit_exit("Expiration processing liquidation")

    def _submit_exit(self, reason):
        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _handle_unexpected_equity_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.no_entry_today = True
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")

    def OnAssignmentOrderEvent(self, assignment_event):
        self.no_entry_today = True
        self.Debug("Unexpected assignment event received.")

        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Assignment-created SPY liquidation"
            )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call exit filled.")
