            self._bucket_close = spy_bar.Close
            return

        completed_end = self._bucket + timedelta(minutes=5)
        completed_close = self._bucket_close

        self._bucket = bucket
        self._bucket_close = spy_bar.Close

        self._process_five_minute_bar(
            completed_end,
            completed_close,
            slice
        )

    def _process_five_minute_bar(self, end_time, close, slice):
