        if selected is None:
            self.Debug("Skipped call selection: no qualifying contract")
            return

        self._entry_symbol = selected.Symbol
        self._entry_price = None
        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Call entry submitted: " + str(selected.Symbol))

    def _select_call(self, slice, spy_price):
        minimum_expiry = self.Time.date() + timedelta(days=7)
        chains = getattr(slice.OptionChains, "Values", [])

        contracts = []
        for chain in chains:
            for contract in chain.Contracts.Values:
                expiry_date = contract.Expiry.date()
                if expiry_date < minimum_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < spy_price * 1.01:
                    continue
                contracts.append(contract)

        if not contracts:
            return None

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        return min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

