        if self._entry_symbol is None or self._entry_price is None:
            return

        quantity = self.Portfolio[self._entry_symbol].Quantity
        if quantity <= 0:
            return

        expiry = self.Securities[self._entry_symbol].Symbol.ID.Date.date()
        current_date = self.Time.date()

        preceding_trading_day = self._preceding_trading_day(expiry)
        time_stop = (
            current_date == preceding_trading_day and
            self.Time.time() >= time(15, 45)
        )

        midpoint = self._current_option_midpoint(slice, self._entry_symbol)
        profit_target = (
            midpoint is not None and
            midpoint >= 1.50 * self._entry_price
        )

        if profit_target:
            self._submit_exit("profit target")
        elif time_stop:
            self._submit_exit("expiration time stop")

    def _current_option_midpoint(self, slice, symbol):
        for chain in getattr(slice.OptionChains, "Values", []):
            contract = chain.Contracts.get(symbol)
            if contract is None:
                continue

            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)
            if bid > 0 and ask > 0:
                return (bid + ask) / 2.0

        return None

    def _submit_exit(self, reason):
        if self._entry_symbol is None:
            return

        quantity = self.Portfolio[self._entry_symbol].Quantity
        if quantity <= 0 or self._exit_ticket_is_open():
            return

        if reason == "profit target":
            self._cancel_open_exit_order()

        self._exit_ticket = self.MarketOrder(
            self._entry_symbol,
            -quantity
        )
        self.Debug("Call exit submitted: " + reason)

    def _handle_expiration_processing(self, current_date):
        if self._entry_symbol is None:
            return

        expiry = self.Securities[self._entry_symbol].Symbol.ID.Date.date()
        if current_date >= expiry:
            self._blocked_entry_date = current_date
            self._submit_exit("expiration processing")

    def _handle_unexpected_equity_position(self):
        holding = self.Portfolio[self.spy]
        if holding.Quantity != 0:
            self.Debug("Unexpected SPY exercise or assignment; liquidating equity")
            self.MarketOrder(self.spy, -holding.Quantity)
            self._blocked_entry_date = self.Time.date()

    def _preceding_trading_day(self, expiry_date):
        day = expiry_date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(day):
            day -= timedelta(days=1)

        return day

    def _entry_ticket_is_open(self):
        if self._entry_ticket is None:
            return False

        return self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

    def _exit_ticket_is_open(self):
        if self._exit_ticket is None:
            return False

        return self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.UpdateSubmitted
        )

    def _cancel_open_exit_order(self):
        if self._exit_ticket_is_open():
            self._exit_ticket.Cancel("Replacing exit order")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self._entry_ticket is not None and
            order_event.OrderId == self._entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self._entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self._entry_symbol,
                        self._entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Call entry skipped: entry order not filled")
                self._entry_ticket = None
                self._entry_symbol = None
                self._entry_price = None

        if (
            self._exit_ticket is not None and
            order_event.OrderId == self._exit_ticket.OrderId and
            order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call position exited: " + str(self._entry_symbol))
            self._exit_ticket = None
            self._entry_ticket = None
            self._entry_symbol = None
            self._entry_price = None

