            return

        if self._entry_ticket is not None and self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            return

        chain = None
        try:
            if self._option_symbol in slice.OptionChains:
                chain = slice.OptionChains[self._option_symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        spy_bar = slice.Bars.get(self._spy)
        price = spy_bar.Close if spy_bar is not None else self.Securities[self._spy].Price

