        minimum_strike = float(price) * 1.01

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _check_profit_target(self, slice):
        if self._held_symbol is None or self._entry_price is None:
            return
        if self._exit_ticket is not None and self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        midpoint = None

        try:
            for chain in slice.OptionChains.Values:
                for contract in chain:
                    if contract.Symbol == self._held_symbol:
                        bid = contract.BidPrice
                        ask = contract.AskPrice
                        if bid > 0 and ask > 0:
                            midpoint = (bid + ask) / 2.0
