        if self._held_symbol is None:
            return
        if self._exit_ticket is not None and self._exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            return

        if self._entry_ticket is not None and self._entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        ):
            self._entry_ticket.Cancel("Exit required")

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity != 0:
            self._exit_ticket = self.MarketOrder(
                self._held_symbol,
                -quantity,
                tag=tag
            )
            self.Debug("Exit submitted: {}".format(tag))

    def OnOrderEvent(self, order_event):
        if self._entry_ticket is not None and order_event.OrderId == self._entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
