                    "Entry filled: {} at {:.4f}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self._entry_ticket = None

        if self._exit_ticket is not None and order_event.OrderId == self._exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self._exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment or exercise received.")
        quantity = self.Portfolio[self._spy].Quantity
        if quantity != 0:
            self.MarketOrder(
                self._spy,
                -quantity,
                tag="Unexpected assignment liquidation"
            )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self._spy_hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
        return candidate

