from collections import deque
from datetime import timedelta

from QuantConnect import Resolution, DataNormalizationMode, OptionRight
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Orders import OrderStatus


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = option.Symbol
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice):
        self.current_slice = slice

        self._handle_unexpected_spy_position()
        self._handle_expiration_processing()
        self._evaluate_option_exit()

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar)

    def _process_minute_bar(self, bar):
        bar_time = bar.Time
        if bar_time.date() < self.StartDate.date():
            return

        if bar_time.hour < 9 or (bar_time.hour == 9 and bar_time.minute < 30):
            return
        if bar_time.hour > 16 or (bar_time.hour == 16 and bar_time.minute >= 0):
            return

        block_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=block_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._complete_bucket()
            self.bucket_start = bucket_start
            self.bucket_bars = []

        if bar_time not in [item.Time for item in self.bucket_bars]:
            self.bucket_bars.append(bar)

    def _complete_bucket(self):
        if self.bucket_start is None:
            return

        expected_end = self.bucket_start + timedelta(minutes=5)

        if len(self.bucket_bars) != 5:
            self.bucket_bars = []
            return

        minute_times = sorted(item.Time for item in self.bucket_bars)
        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if minute_times != expected_times:
            self.bucket_bars = []
            return

        if expected_end.time() < self._time(9, 45) or expected_end.time() > self._time(14, 30):
            self._update_averages(self.bucket_bars[-1].Close, expected_end)
            self.bucket_bars = []
            return

        self._update_averages(self.bucket_bars[-1].Close, expected_end)
        self.bucket_bars = []

    def _update_averages(self, close, bar_end):
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.closes.append(float(close))

        current_fast = None
        current_slow = None

        if len(self.closes) >= 5:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
        if len(self.closes) >= 20:
            current_slow = sum(self.closes) / 20.0

        signal = (
            bar_end.time() >= self._time(9, 45)
            and bar_end.time() <= self._time(14, 30)
            and prior_fast is not None
            and prior_slow is not None
            and current_fast is not None
            and current_slow is not None
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if signal:
            self._try_enter_call(float(close))

    def _try_enter_call(self, spy_price):
        current_date = self.Time.date()

        if self.blocked_entry_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        if self.current_slice is None or self.option_symbol not in self.current_slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        chain = self.current_slice.OptionChains[self.option_symbol]
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
