        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar)

    def _process_minute_bar(self, bar):
        bar_time = bar.Time
        if bar_time.date() < self.StartDate.date():
            return

        if bar_time.hour < 9 or (bar_time.hour == 9 and bar_time.minute < 30):
            return
        if bar_time.hour > 16 or (bar_time.hour == 16 and bar_time.minute >= 0):
            return

        block_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=block_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start != self.bucket_start:
            self._complete_bucket()
            self.bucket_start = bucket_start
            self.bucket_bars = []

        if bar_time not in [item.Time for item in self.bucket_bars]:
            self.bucket_bars.append(bar)

