from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )

        self.close_history = deque(maxlen=20)
        self.current_bucket_end = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.held_expiry = None
        self.held_previous_trading_day = None
        self.expiration_block_date = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()
        current_time = self.Time.time()

        if self.Portfolio[self.spy].Quantity != 0:
            self.Debug("Unexpected SPY equity position; liquidating immediately.")
            self.MarketOrder(self.spy, -self.Portfolio[self.spy].Quantity)
            self.expiration_block_date = current_date

        if self.held_symbol is not None:
            if self.held_expiry is not None and current_date >= self.held_expiry:
                self.expiration_block_date = current_date
                self._submit_exit("expiration processing")

            elif (
                self.held_previous_trading_day == current_date
                and current_time >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")

            else:
                self._check_profit_target(data)

        spy_bar = data.Bars[self.spy] if self.spy in data.Bars else None
        if spy_bar is None:
            return

        bar_end = spy_bar.EndTime.astimezone(self.TimeZone)
        if bar_end.date() != current_date:
            return

        if not (time(9, 31) <= bar_end.time() <= time(16, 0)):
            return

        bucket_end = self._bucket_end(bar_end)
        if self.current_bucket_end is None:
            self.current_bucket_end = bucket_end
        elif bucket_end != self.current_bucket_end:
            self._complete_bucket(data)
            self.current_bucket_end = bucket_end
            self.current_bucket_bars = {}

        self.current_bucket_bars[bar_end] = spy_bar.Close

        if len(self.current_bucket_bars) == 5:
            self._complete_bucket(data)
            self.current_bucket_bars = {}
            self.current_bucket_end = None

    def _bucket_end(self, bar_end):
        session_start = datetime.combine(
            bar_end.date(),
            time(9, 30),
            tzinfo=bar_end.tzinfo
        )
        minutes = int((bar_end - session_start).total_seconds() // 60)
        end_offset = ((minutes + 4) // 5) * 5
        return session_start + timedelta(minutes=end_offset)

    def _complete_bucket(self, data):
        if self.current_bucket_end is None:
            return

        expected = [
            self.current_bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if any(timestamp not in self.current_bucket_bars for timestamp in expected):
            return

        close = self.current_bucket_bars[expected[-1]]
        previous_fast = None
        previous_slow = None
        if len(self.close_history) >= 20:
            previous_fast = sum(list(self.close_history)[-5:]) / 5.0
            previous_slow = sum(self.close_history) / 20.0

        self.close_history.append(close)

        if len(self.close_history) < 20:
            return

        current_fast = sum(list(self.close_history)[-5:]) / 5.0
        current_slow = sum(self.close_history) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bar_end_local = self.current_bucket_end.astimezone(self.TimeZone)
        eligible_time = time(9, 45) <= bar_end_local.time() <= time(14, 30)

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if eligible_time and bullish_cross:
            self._try_enter(data, close)

    def _try_enter(self, data, spy_price):
        if self.expiration_block_date == self.Time.date():
            return

        if self.entry_ticket is not None:
            if self.entry_ticket.Status in [
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ]:
                return

        if self.held_symbol is not None or self._has_option_holding():
            return

        chain = None
        for candidate in data.OptionChains.Values:
            if candidate.Symbol == self.spy_option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        contracts = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not contracts:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        contract = min(
            contracts,
            key=lambda item: (item.Strike, str(item.Symbol))
        )

        self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
        self.Debug("Call entry submitted: " + str(contract.Symbol))

    def _check_profit_target(self, data):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != self.held_symbol:
                    continue

                bid = contract.BidPrice
                ask = contract.AskPrice

                if bid is not None and ask is not None and bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_price:
                        self._submit_exit("50% profit target")
                return

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]:
            self.entry_ticket.Cancel("Exit requested.")

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Call exit submitted: " + reason)

    def _has_option_holding(self):
        for holding in self.Portfolio.Values:
            if holding.Quantity == 0:
                continue
            security = self.Securities[holding.Symbol]
            if security.Type == SecurityType.Option:
                return True
        return False

    def OnOrderEvent(self, order_event):
        if (
            getattr(order_event, "IsAssignment", False)
            or order_event.OrderType == OrderType.OptionExercise
        ):
            self.Debug("Unexpected option exercise or assignment handling.")
            self.expiration_block_date = self.Time.date()

            quantity = self.Portfolio[self.spy].Quantity
            if quantity != 0:
                self.MarketOrder(self.spy, -quantity)

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.held_expiry = order_event.Symbol.ID.Date.date()

                try:
                    self.held_previous_trading_day = (
                        self.Securities[self.spy]
                        .Exchange
                        .Hours
                        .GetPreviousTradingDay(self.held_expiry)
                        .date()
                    )
                except Exception:
                    previous_day = self.held_expiry - timedelta(days=1)
                    while previous_day.weekday() >= 5:
                        previous_day -= timedelta(days=1)
                    self.held_previous_trading_day = previous_day

                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )

            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Call exit filled: " + str(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.held_expiry = None
                self.held_previous_trading_day = None
                self.exit_ticket = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket = None

