                "high": bar.High,
                "low": bar.Low,
                "close": bar.Close,
                "volume": bar.Volume
            }
        else:
            self.bucket["high"] = max(self.bucket["high"], bar.High)
            self.bucket["low"] = min(self.bucket["low"], bar.Low)
            self.bucket["close"] = bar.Close
            self.bucket["volume"] += bar.Volume

