            if (
                (bar_end.hour > 9 or
                 (bar_end.hour == 9 and bar_end.minute >= 45)) and
                (bar_end.hour < 14 or
                 (bar_end.hour == 14 and bar_end.minute <= 30))
            ):
                self._try_enter(self._current_slice, close)

