        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if slice is None or slice.QuoteBars is None:
            return

        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration_and_time_stop(self):
        if self.held_symbol is None or self.held_expiry is None:
            return

        current_date = self.Time.date()

        if current_date >= self.held_expiry:
            self.expiry_block_date = current_date
            if self.Portfolio[self.held_symbol].Quantity > 0:
                self._submit_exit("Expiration protection")
            return

        if (
            current_date == self.held_expiry - timedelta(days=1) and
            (self.Time.hour > 15 or
             (self.Time.hour == 15 and self.Time.minute >= 45))
        ):
            self._submit_exit("Expiration-eve time stop")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None and not self.exit_ticket.Status.IsClosed():
            self.exit_ticket.Cancel("Replacing exit with liquidation market order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_symbol} ({reason})")

    def _handle_unexpected_spy_position(self):
        quantity = self.Portfolio[self.spy.Symbol].Quantity
        if quantity != 0:
            self.Debug("Unexpected SPY equity position detected; liquidating immediately.")
            self.MarketOrder(
                self.spy.Symbol,
                -quantity,
                tag="Unexpected exercise or assignment handling"
            )

    def _has_option_holding(self):
        for security in self.Securities.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option and
                self.Portfolio[security.Symbol].Quantity > 0
            ):
                return True
        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.IsAssignment:
            self.Debug("Unexpected option exercise or assignment detected.")
            quantity = self.Portfolio[self.spy.Symbol].Quantity
            if quantity != 0:
                self.MarketOrder(
                    self.spy.Symbol,
                    -quantity,
                    tag="Unexpected exercise or assignment handling"
                )

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.held_expiry = self.Securities[
                    order_event.Symbol
                ].Symbol.ID.Date.date()
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status.IsClosed() and self.held_symbol is None:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {order_event.Symbol}")
                if self.Portfolio[order_event.Symbol].Quantity <= 0:
                    self.held_symbol = None
                    self.held_expiry = None
                    self.entry_price = None
                    self.exit_ticket = None

    def OnEndOfAlgorithm(self):
        if self.bucket is not None:
            self._process_completed_bucket()

