        self._handle_expiration(today)
        self._evaluate_profit_target(slice)
        self._evaluate_time_stop(today)

    def _on_five_minute_bar(self, sender, bar: TradeBar):
        bar_time = bar.EndTime.time()

        if bar_time < time(9, 45) or bar_time > time(14, 30):
            self._update_averages(bar)
            return

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self._update_averages(bar)

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_crossover:
            self._try_entry(self.CurrentSlice)

    def _update_averages(self, bar: TradeBar):
        point = IndicatorDataPoint(bar.EndTime, bar.Close)
        self.fast.Update(point)
        self.slow.Update(point)

    def _try_entry(self, slice: Slice):
        today = self.Time.date()

        if self._no_entry_date == today:
            return

        if self._entry_order_is_open():
            return

        if self._held_symbol is not None and self.Portfolio[self._held_symbol].Invested:
            return

        chain = None
        for candidate in slice.OptionChains:
            if candidate.Key == self.option.Symbol:
                chain = candidate.Value
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain.")
            return

        current_price = self.Securities[self.spy].Price
        if current_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = list(chain)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = current_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._held_symbol = selected.Symbol
        self._entry_price = None
        self._time_stop_date = self._previous_trading_day(selected_expiry)
        self._time_stop_submitted_date = None

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, selected_expiry, selected.Strike
            )
        )

