        if self._entry_ticket is not None:
            if order_event.OrderId == self._entry_ticket.OrderId:
                if order_event.FillQuantity > 0:
                    self._entry_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self._held_symbol, self._entry_price
                        )
                    )

                if order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.Debug("Entry order did not complete.")
                    self._entry_ticket = None
                    self._held_symbol = None
                    self._entry_price = None

        if self._exit_ticket is not None:
            if order_event.OrderId == self._exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {0}".format(self._held_symbol))
                    self._exit_ticket = None
                    self._entry_price = None
                    self._held_symbol = None
                    self._time_stop_date = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self._exit_ticket = None

    def _evaluate_profit_target(self, slice: Slice):
        if self._held_symbol is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested or self._exit_order_is_open():
            return

        quote = slice.BidAskBars.get(self._held_symbol)
        if quote is None or quote.Bid <= 0 or quote.Ask <= 0:
            return

        midpoint = (quote.Bid + quote.Ask) / 2.0
        if midpoint < self._entry_price * 1.5:
            return

        self._submit_exit("50% profit target")

    def _evaluate_time_stop(self, today):
        if self._held_symbol is None or self._time_stop_date != today:
            return

        if self.Time.time() < time(15, 45):
            return

        if self._time_stop_submitted_date == today:
            return

        if self.Portfolio[self._held_symbol].Invested:
            self._submit_exit("expiration-eve time stop")
            self._time_stop_submitted_date = today

    def _handle_expiration(self, today):
        if self._held_symbol is None:
            return

        security = self.Securities[self._held_symbol]
        expiry = security.Symbol.ID.Date.date()

        if today >= expiry:
            self._no_entry_date = today
            if self.Portfolio[self._held_symbol].Invested:
                self._submit_exit("expiration protection")

    def _handle_unexpected_spy_position(self, today):
        holding = self.Portfolio[self.spy]
        if not holding.Invested:
            self._equity_liquidation_submitted = False
            return

        self._no_entry_date = today

        if not self._equity_liquidation_submitted:
            self.Debug("Unexpected exercise or assignment: liquidating SPY.")
            self.MarketOrder(self.spy, -holding.Quantity)
            self._equity_liquidation_submitted = True

    def _submit_exit(self, reason):
        if self._held_symbol is None:
            return

        holding = self.Portfolio[self._held_symbol]
        if not holding.Invested:
            return

        if self._exit_ticket is not None and self._exit_order_is_open():
            self._exit_ticket.Cancel("Replacing with higher-priority exit")

        quantity = -holding.Quantity
        self._exit_ticket = self.MarketOrder(self._held_symbol, quantity)
        self.Debug("Exit submitted: {0} ({1})".format(self._held_symbol, reason))

    def _entry_order_is_open(self):
        return (
            self._entry_ticket is not None
            and self._entry_ticket.Status.IsOpen()
        )

    def _exit_order_is_open(self):
        return (
            self._exit_ticket is not None
            and self._exit_ticket.Status.IsOpen()
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate

