from AlgorithmImports import *
from datetime import timedelta, time


class SpyBullishCrossoverCall(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy.Symbol, self.consolidator)

        self.pending_entry_signal = False
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.expiration_block_date = None
        self.equity_liquidation_ticket = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime.time()

        if bar_time < time(9, 35) or bar_time > time(16, 0):
            return

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if previous_fast is None or previous_slow is None:
            return

        eligible_time = time(9, 45) <= bar_time <= time(14, 30)
        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if eligible_time and bullish_crossover:
            self.pending_entry_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing(current_date)

        if self.held_option is not None:
            self.HandleOptionExit(slice, current_date)

        if self.pending_entry_signal:
            self.pending_entry_signal = False

            if self.expiration_block_date == current_date:
                return

            if self.held_option is not None:
                return

            if self.entry_ticket is not None and self.IsOpen(self.entry_ticket):
                return

            self.TryEnter(slice)

    def TryEnter(self, slice):
        chain = slice.OptionChains.get(self.option.Symbol, None)

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        spy_price = self.Securities[self.spy.Symbol].Price
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)

        contracts = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
            and contract.Strike >= 1.01 * spy_price
        ]

        if not contracts:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)

        contracts = [
            contract for contract in contracts
            if contract.Expiry.date() == nearest_expiry
        ]

        selected = min(
            contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        if self.entry_ticket is not None:
            self.Debug(
                "Entry submitted: {0}, expiry {1}, strike {2}".format(
                    selected.Symbol,
                    selected.Expiry.date(),
                    selected.Strike
                )
            )

    def HandleOptionExit(self, slice, current_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self.SubmitOptionLiquidation("expiration")
            return

        previous_trading_day = self.GetPreviousTradingDay(expiry_date)

        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitOptionLiquidation("time stop")
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quote = slice.QuoteBars.get(self.held_option, None)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self.SubmitOptionLiquidation("50% profit target")

    def SubmitOptionLiquidation(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self.IsOpen(self.exit_ticket):
            return

        quantity = -self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_option, quantity)
        self.Debug("Exit submitted: {0} ({1})".format(self.held_option, reason))

    def HandleExpirationProcessing(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()

        if current_date >= expiry_date:
            self.expiration_block_date = current_date
            self.SubmitOptionLiquidation("expiration processing")

    def HandleUnexpectedEquityPosition(self):
        holding = self.Portfolio[self.spy.Symbol]

        if not holding.Invested:
            return

        self.Debug("Unexpected SPY equity position; liquidating immediately.")

        if (
            self.equity_liquidation_ticket is None
            or not self.IsOpen(self.equity_liquidation_ticket)
        ):
            self.equity_liquidation_ticket = self.MarketOrder(
                self.spy.Symbol,
                -holding.Quantity
            )

    def GetPreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def IsOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
