        current_date = local_time.date()
        current_time = local_time.time()

        if current_time < time(9, 30) or current_time >= time(16, 0):
            return

        bucket = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            current_time.hour,
            (current_time.minute // 5) * 5
        )

        if self.bucket_start is not None and bucket != self.bucket_start:
            self._complete_five_minute_bar()

        if self.bucket_start != bucket:
            self.bucket_start = bucket
            self.bucket_close = bar.Close
            self.bucket_count = 1
            self.bucket_valid = True
            self.expected_minute = bar.Time + timedelta(minutes=1)
            return

        if bar.Time != self.expected_minute:
            self.bucket_valid = False

        self.bucket_count += 1
        self.bucket_close = bar.Close
        self.expected_minute = bar.Time + timedelta(minutes=1)

    def _complete_five_minute_bar(self):
        if self.bucket_start is None:
            return

        bar_end = self.bucket_start + timedelta(minutes=5)

        if self.bucket_count != 5 or not self.bucket_valid:
            self.Debug("Skipped missing SPY five-minute bar at {}".format(bar_end))
            return

        prior_fast = self.fast.Current.Value if self.fast.IsReady else None
        prior_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar_end, self.bucket_close)
        self.slow.Update(bar_end, self.bucket_close)

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            self.fast.IsReady and
            self.slow.IsReady and
            prior_fast <= prior_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter_call(self.bucket_close, bar_end)

        if self.fast.IsReady and self.slow.IsReady:
            self.previous_fast = self.fast.Current.Value
            self.previous_slow = self.slow.Current.Value

    def _try_enter_call(self, spy_price, bar_end):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_symbol is not None or self._has_open_entry_order():
