            expirations = sorted({
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry
            })

            if not expirations:
                self.Debug("Skipped entry: no valid expiration")
                return

            selected_expiry = expirations[0]
            minimum_strike = 1.01 * float(spy_price)

            contracts = [
                contract for contract in chain
                if contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and float(contract.Strike) >= minimum_strike
            ]

            if not contracts:
                self.Debug("Skipped entry: no qualifying call")
                return

            contracts.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
            contract = contracts[0]

            self.entry_ticket = self.MarketOrder(contract.Symbol, 1)
            self.Debug(
                "Entry submitted: {} expiring {}".format(
                    contract.Symbol, selected_expiry
                )
            )

        except Exception:
            self.Debug("Skipped entry: option selection unavailable")

    def _process_option_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if not self.Portfolio[self.held_symbol].Invested:
            return

        if self._has_open_exit_order():
            return

        current_date = self.Time.date()
        current_time = self.Time.time()

        if (
            self.time_stop_date == current_date
            and current_time >= time(15, 45)
        ):
            self._submit_exit("time stop")
            return

        bid = None
        ask = None

        if self.held_symbol in slice.QuoteBars:
            quote = slice.QuoteBars[self.held_symbol]
            if quote.Bid is not None:
                bid = float(quote.Bid.Close)
            if quote.Ask is not None:
                ask = float(quote.Ask.Close)

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {} ({})".format(self.held_symbol, reason)
        )

    def _process_expiration(self):
        if self.expiration_date is None:
            return

        current_date = self.Time.date()
        if current_date < self.expiration_date:
            return

        self.no_entry_date = current_date

        if self._has_open_entry_order():
            self.entry_ticket.Cancel("expiration processing")
            self.Debug("Canceled entry during expiration processing")

        if (
            self.held_symbol is not None
            and self.Portfolio[self.held_symbol].Invested
            and not self._has_open_exit_order()
        ):
            self._submit_exit("expiration protection")
            self.Debug("Expiration protection exit submitted")

    def _liquidate_unexpected_spy_position(self):
        holdings = self.Portfolio[self.spy]
        if holdings.Quantity == 0:
            return

        self.MarketOrder(
            self.spy,
            -holdings.Quantity,
            tag="unexpected exercise or assignment"
        )
        self.Debug("Unexpected SPY exercise or assignment position liquidated")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = self.Securities[
                    self.held_symbol
                ].Symbol.ID.Date.date()

                self.time_stop_date = self._previous_trading_day(
                    self.expiration_date
                )

                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.PartiallyFilled
            ) and not self.Portfolio[order_event.Symbol].Invested:
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {:.4f}".format(
                        order_event.Symbol, float(order_event.FillPrice)
                    )
                )
                if not self.Portfolio[order_event.Symbol].Invested:
                    self._clear_position_state()

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option assignment received")
        self._liquidate_unexpected_spy_position()

    def OnExerciseOrderEvent(self, exercise_event: OrderEvent):
        self.Debug("Unexpected option exercise received")
        self._liquidate_unexpected_spy_position()

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _has_open_entry_order(self):
        return (
            self.entry_ticket is not None
            and self.entry_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _has_open_exit_order(self):
        return (
            self.exit_ticket is not None
            and self.exit_ticket.Status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            )
        )

    def _clear_position_state(self):
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None

