from datetime import datetime, timedelta, time


class SpyBullishCallStrategy(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.closes = []
        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_dates = set()
        self.assignment_liquidation_ticket = None

    def OnData(self, slice: Slice):
        now = self.Time
        today = now.date()

        self._handle_unexpected_equity_position(today)
        self._handle_expiration_processing(today)

        spy_bar = None
        if self.spy in slice.Bars:
            spy_bar = slice.Bars[self.spy]

        if spy_bar is not None:
            self._process_spy_minute(spy_bar, slice)

        self._evaluate_option_exit(slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_time = end_time.time()

        # Regular-session minute bars end from 09:31 through 16:00.
        if local_time < time(9, 31) or local_time > time(16, 0):
            return

        minute = end_time.minute
        bucket_minute = ((minute + 4) // 5) * 5
        bucket_hour = end_time.hour

        if bucket_minute >= 60:
            bucket_hour += 1
            bucket_minute = 0

        bucket_end = datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            bucket_hour,
            bucket_minute
        )

        if self.bucket_end is None:
            self.bucket_date = end_time.date()
            self.bucket_end = bucket_end
        elif bucket_end != self.bucket_end:
            self._complete_bucket(slice)
            self.bucket_date = end_time.date()
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end_time] = bar

    def _complete_bucket(self, slice: Slice):
        if self.bucket_end is None:
            return

        expected_times = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        # Missing minutes invalidate the five-minute bar entirely.
        if any(t not in self.bucket_bars for t in expected_times):
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        close = bars[-1].Close

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0

        self.closes.append(close)
        if len(self.closes) > 20:
            self.closes = self.closes[-20:]

        if len(self.closes) < 20:
            self.bucket_bars = {}
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_time = self.bucket_end.time()
        eligible_time = time(9, 45) <= bar_time <= time(14, 30)

        if crossover and eligible_time:
            self._try_entry(slice, close)

        self.bucket_bars = {}

    def _try_entry(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if today in self.blocked_dates:
            return

        if self.held_option is not None:
            return

        if self._order_is_open(self.entry_ticket):
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = today + timedelta(days=7)
        contracts = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(contract.Expiry.date() for contract in contracts)

        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= 1.01 * spy_price
        ]

        if not eligible:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            eligible,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={selected.Expiry.date()}, strike={selected.Strike}"
        )

    def _evaluate_option_exit(self, slice: Slice):
        if self.held_option is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        symbol = self.held_option
        quantity = self.Portfolio[symbol].Quantity
        if quantity <= 0:
            return

        expiry_date = symbol.ID.Date.date()

        # Expiration-date processing takes priority over quote-based exits.
        if self.Time.date() >= expiry_date:
            self.blocked_dates.add(self.Time.date())
            self._submit_exit("Expiration protection")
            return

        stop_date = self._previous_trading_date(expiry_date)
        if self.Time.date() == stop_date and self.Time.time() >= time(15, 45):
            self._submit_exit("Pre-expiration time stop")
            return

        if symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if self.entry_price is not None and midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self._order_is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {self.held_option}, reason={reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.held_option}, "
                    f"price={self.entry_price}"
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {self.exit_ticket.Symbol}, "
                    f"price={order_event.FillPrice}"
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.Debug("Unexpected option exercise or assignment detected.")
            self.blocked_dates.add(self.Time.date())

    def _handle_expiration_processing(self, today):
        if self.held_option is None:
            return

        expiry_date = self.held_option.ID.Date.date()
        if today >= expiry_date:
            self.blocked_dates.add(today)
            self._submit_exit("Expiration processing")

    def _handle_unexpected_equity_position(self, today):
        if self.spy not in self.Portfolio:
            return

        quantity = self.Portfolio[self.spy].Quantity
        if quantity == 0:
            return

        if not self._order_is_open(self.assignment_liquidation_ticket):
            self.Debug(
                f"Unexpected SPY equity position detected: quantity={quantity}. "
                "Liquidating immediately."
            )
            self.blocked_dates.add(today)
            self.assignment_liquidation_ticket = self.MarketOrder(
                self.spy,
                -quantity,
                tag="Unexpected exercise or assignment liquidation"
            )

    def _previous_trading_date(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _order_is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.None
        )

