class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)
        self.fast_values = RollingWindow[float](2)
        self.slow_values = RollingWindow[float](2)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.current_chain = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.equity_liquidation_submitted = False
        self.expiration_block_date = None

    def OnData(self, data):
        current_date = self.Time.date()

        self.current_chain = None
        if self.option_symbol in data.OptionChains:
            self.current_chain = data.OptionChains[self.option_symbol]

        self.HandleUnexpectedEquityPosition()
        self.HandleExpirationProcessing(current_date)
        self.HandleOptionExit(data, current_date)

        if self.spy in data:
            self.consolidator.Update(data[self.spy])

    def OnFiveMinuteBar(self, sender, bar):
        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        self.fast_values.Add(float(self.fast.Current.Value))
        self.slow_values.Add(float(self.slow.Current.Value))

        if not self.fast_values.IsReady or not self.slow_values.IsReady:
            return

        bar_time = bar.EndTime.time()
        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        bullish_crossover = (
            self.fast_values[1] <= self.slow_values[1] and
            self.fast_values[0] > self.slow_values[0]
        )

        if bullish_crossover:
            self.TryEnterCall()

    def TryEnterCall(self):
        current_date = self.Time.date()

        if self.expiration_block_date == current_date:
            return

        if self.held_option is not None:
            return

        if self.IsEntryOrderOpen():
            return

        if self.current_chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        if self.spy not in self.Securities:
            return

        spy_price = float(self.Securities[self.spy].Price)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in self.current_chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in self.current_chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def HandleOptionExit(self, data, current_date):
        if self.held_option is None or self.entry_price is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        contract = self.GetCurrentOptionContract(data, self.held_option)

        if contract is not None:
            bid = float(contract.BidPrice)
            ask = float(contract.AskPrice)

            if bid > 0 and ask > 0:
                midpoint = (bid + ask) / 2.0
                if midpoint >= 1.50 * self.entry_price:
                    self.SubmitExit("50% profit target")
                    return

        expiry_date = self.GetHeldExpiryDate()
        if expiry_date is None:
            return

        previous_trading_day = self.GetPreviousTradingDay(expiry_date)
        if (
            current_date == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("Expiration time stop")

    def HandleExpirationProcessing(self, current_date):
        if self.held_option is None:
            return

        expiry_date = self.GetHeldExpiryDate()
        if expiry_date is None or current_date < expiry_date:
            return

        self.expiration_block_date = current_date

        if self.IsEntryOrderOpen():
            self.entry_ticket.Cancel("Expiration processing")

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity != 0:
            self.SubmitExit("Expiration processing liquidation")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

    def GetCurrentOptionContract(self, data, symbol):
        if self.option_symbol not in data.OptionChains:
            return None

        for contract in data.OptionChains[self.option_symbol]:
            if contract.Symbol == symbol:
                return contract

        return None

    def GetHeldExpiryDate(self):
        if self.held_option is None:
            return None

        security = self.Securities.Get(self.held_option)
        if security is None:
            return None

        return security.Symbol.ID.Date.date()

    def GetPreviousTradingDay(self, date_value):
        candidate = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        ) - timedelta(days=1)

        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def HandleUnexpectedEquityPosition(self):
        quantity = self.Portfolio[self.spy].Quantity

        if quantity != 0:
            if not self.equity_liquidation_submitted:
                self.Debug("Unexpected exercise or assignment: liquidating SPY.")
                self.MarketOrder(
                    self.spy,
                    -quantity,
                    tag="Unexpected exercise or assignment liquidation"
                )
                self.equity_liquidation_submitted = True
        else:
            self.equity_liquidation_submitted = False

    def IsEntryOrderOpen(self):
        return self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket)

    def IsOrderOpen(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_option = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entered 1 SPY call: {} at {:.4f}".format(
                        self.held_option,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exited SPY call: {} at {:.4f}".format(
                        self.exit_ticket.Symbol,
                        float(order_event.FillPrice)
                    )
                )
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

