from AlgorithmImports import *
from datetime import timedelta, time, datetime


class SpyBullishCrossoverOptionAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self._on_five_minute_bar

        self.entry_order_id = None
        self.exit_order_id = None
        self.held_option = None
        self.entry_price = None
        self.time_stop_date = None
        self.no_entry_today = False
        self.pending_entry_bar = None

    def _on_five_minute_bar(self, sender, bar):
        end_time = bar.EndTime.time()

        if end_time < time(9, 35) or end_time > time(16, 0):
            return

        previous_fast = None
        previous_slow = None

        if self.closes.Count >= self.slow_period:
            previous_fast = sum(
                self.closes[i] for i in range(self.fast_period)
            ) / self.fast_period
            previous_slow = sum(
                self.closes[i] for i in range(self.slow_period)
            ) / self.slow_period

        self.closes.Add(float(bar.Close))

        if self.closes.Count < self.slow_period:
            return

        current_fast = sum(
            self.closes[i] for i in range(self.fast_period)
        ) / self.fast_period
        current_slow = sum(
            self.closes[i] for i in range(self.slow_period)
        ) / self.slow_period

        if previous_fast is None or previous_slow is None:
            return

        if not (
            previous_fast <= previous_slow
            and current_fast > current_slow
        ):
            return

        if time(9, 45) <= end_time <= time(14, 30):
            self.pending_entry_bar = bar

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.no_entry_today is False:
            self.no_entry_today = False

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_today = True
                self._submit_exit("expiration processing")
            elif (
                self.time_stop_date is not None
                and today == self.time_stop_date
                and self.Time.time() >= time(15, 45)
            ):
                self._submit_exit("expiration time stop")
            else:
                self._check_profit_target(slice)

        if self.spy in slice.Bars:
            self.consolidator.Update(slice.Bars[self.spy])

        if self.pending_entry_bar is not None:
            signal_bar = self.pending_entry_bar
            self.pending_entry_bar = None
            self._evaluate_entry(slice, signal_bar)

    def _evaluate_entry(self, slice: Slice, signal_bar):
        if self.no_entry_today:
            return

        if self.held_option is not None:
            return

        if self.entry_order_id is not None:
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped selection: no current SPY price.")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        if spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped selection: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped selection: no expiration at least 7 days away.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = 1.01 * spy_price
        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_order_id = None
        ticket = self.MarketOrder(selected.Symbol, 1)

        if ticket is not None:
            self.entry_order_id = ticket.OrderId
            self.Debug(
                "Entry submitted: {} strike {} expiry {}".format(
                    selected.Symbol,
                    selected.Strike,
                    selected.Expiry.date()
                )
            )

    def _check_profit_target(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_order_id is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = None
        for contract in chain:
            if contract.Symbol == self.held_option.Symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option.Symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if ticket is not None and ticket.Status.IsOpen():
                ticket.Cancel("Replacing exit order")

        ticket = self.MarketOrder(self.held_option.Symbol, -quantity)
        if ticket is not None:
            self.exit_order_id = ticket.OrderId
            self.Debug(
                "Exit submitted: {} ({})".format(
                    self.held_option.Symbol,
                    reason
                )
            )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time(0))
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        order_id = order_event.OrderId

        if order_id == self.entry_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.entry_order_id = None
                self.held_option = self.Securities[order_event.Symbol]
                self.entry_price = float(order_event.FillPrice)
                expiry_date = self.held_option.Symbol.ID.Date.date()
                self.time_stop_date = self._previous_trading_day(expiry_date)

                self.Debug(
                    "Entry filled: {} at {}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None

        if order_id == self.exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {}".format(
                        order_event.Symbol,
