        local_time = minute_bar.Time.replace(second=0, microsecond=0)
        session_start = local_time.replace(hour=9, minute=30)
        session_end = local_time.replace(hour=16, minute=0)

        if local_time < session_start or local_time >= session_end:
            return None

        if self.last_minute_time == local_time:
            return None
        self.last_minute_time = local_time

        minutes_from_open = int((local_time - session_start).total_seconds() // 60)
        bucket_offset = (minutes_from_open // 5) * 5
        bucket_start = session_start + timedelta(minutes=bucket_offset)

        completed = None

        if self.minute_bucket_start is None:
            self.minute_bucket_date = local_time.date()
            self.minute_bucket_start = bucket_start
            self.minute_bucket_bars = {}
        elif (
            local_time.date() != self.minute_bucket_date
