        threshold = spy_price * 1.01

        candidates = [
            contract for contract in eligible
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped entry: no call strike at least 1% out of the money.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Submitted call entry: " + str(selected.Symbol))

