            return

        if self._exit_order_open():
            return

        contract = slice.OptionChains.get(self.spy_option.Symbol)
        option_data = None

        if contract is not None:
            for item in contract:
                if item.Symbol == self.held_symbol:
                    option_data = item
                    break

        if option_data is None:
            return

        bid = option_data.BidPrice
        ask = option_data.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= self.entry_price * 1.5:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self):
        if self.held_symbol is None or self._exit_order_open():
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        previous_expiry_day = expiry - timedelta(days=1)

        if (
            self.Time.date() == previous_expiry_day
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")

    def _process_expiration_if_needed(self, current_date):
        if self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date < expiry or self.expiration_processed_date == current_date:
            return

        self.expiration_processed_date = current_date
        self.no_entry_date = current_date

        if not self._exit_order_open():
            self._submit_exit("expiration protection")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self._exit_order_open():
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Submitted option exit: " + reason)

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_ticket is not None
                and order_event.OrderId == self.entry_ticket.OrderId
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Option exit filled: " + str(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None

        if getattr(order_event, "IsAssignment", False) or getattr(
            order_event, "IsExercise", False
        ):
            self.no_entry_date = self.Time.date()
            self.Debug("Unexpected option exercise or assignment handled.")

            spy_quantity = self.Portfolio[self.spy].Quantity
            if spy_quantity != 0:
                self.MarketOrder(self.spy, -spy_quantity, tag="Assignment protection")
                self.Debug("Liquidated SPY equity from exercise or assignment.")

