from collections import deque
from datetime import timedelta


class SpyBullishCallStrategy(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.minute_bucket_end = None
        self.minute_bucket = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_symbol = None
        self.held_option = None
        self.held_expiry = None
        self.entry_fill_value = 0.0
        self.entry_filled_quantity = 0
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        # An unexpected SPY position can only be the result of exercise or assignment.
        if self.Portfolio[self.spy].Quantity != 0:
            self.no_entry_date = current_date
            self.Debug(
                "Unexpected SPY equity position detected; liquidating immediately."
            )
            self.MarketOrder(
                self.spy,
                -self.Portfolio[self.spy].Quantity,
                tag="Unexpected exercise/assignment liquidation"
            )

        # Never intentionally carry an option into its expiration date.
        if (
            self.held_option is not None
            and self.held_expiry is not None
            and current_date >= self.held_expiry
        ):
            self.no_entry_date = current_date
            self._submit_exit("Expiration-date liquidation")

        # Evaluate the independent time stop.
        if self.held_option is not None and self.held_expiry is not None:
            previous_trading_day = self._previous_trading_day(self.held_expiry)
            if (
                current_date == previous_trading_day
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("Pre-expiration time stop")

        # Evaluate the profit target from the current Slice only.
        if self.held_option is not None and self.exit_ticket is None:
            contract = self._current_option_contract(slice, self.held_option)
            if contract is not None:
                bid = contract.BidPrice
                ask = contract.AskPrice
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    if midpoint >= 1.50 * self.entry_fill_price:
                        self._submit_exit("50 percent profit target")

        bar = slice.Bars.get(self.spy)
        if bar is None:
            return

        self._process_minute_bar(bar, slice)

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.PartiallyFilled:
                    self._record_entry_fill(order_event)
                elif order_event.Status == OrderStatus.Filled:
                    self._record_entry_fill(order_event)
                    self.entry_ticket = None
                    self.Debug(
                        "Entered 1 SPY call: {0}, fill price {1:.4f}".format(
                            self.held_option, self.entry_fill_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.Debug("Skipped entry: entry order was not filled.")
                    self.entry_ticket = None
                    self.entry_symbol = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exited SPY call: {0}, fill price {1:.4f}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.exit_ticket = None
                    self.held_option = None
                    self.held_expiry = None
                    self.entry_fill_price = 0.0
                    self.entry_filled_quantity = 0
                    self.entry_fill_value = 0.0
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid
                ):
                    self.exit_ticket = None

        if getattr(order_event, "IsAssignment", False):
            self.no_entry_date = self.Time.date()
            self.Debug(
                "Unexpected option exercise or assignment detected; "
                "liquidating SPY equity."
            )
            if self.Portfolio[self.spy].Quantity != 0:
                self.MarketOrder(
                    self.spy,
                    -self.Portfolio[self.spy].Quantity,
                    tag="Exercise/assignment equity liquidation"
                )

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end = bar.EndTime.replace(second=0, microsecond=0)

        if end.time() <= self._time(9, 30) or end.time() > self._time(16, 0):
            return

        bucket_end = self._bucket_end(end)

        if self.minute_bucket_end is not None and bucket_end != self.minute_bucket_end:
            self._complete_bucket()
            self.minute_bucket = []

        if self.minute_bucket_end != bucket_end:
            self.minute_bucket_end = bucket_end

        self.minute_bucket.append((end, float(bar.Close)))

        if end == bucket_end:
            completed_end = bucket_end
            completed = list(self.minute_bucket)
            self.minute_bucket = []
            self.minute_bucket_end = None

            if not self._is_complete_five_minute_bar(completed, completed_end):
                return

            self._handle_five_minute_close(completed[-1][1], completed_end, slice)

    def _complete_bucket(self):
        self.minute_bucket = []
        self.minute_bucket_end = None

    def _handle_five_minute_close(self, close, bar_end, slice: Slice):
        old_fast = None
        old_slow = None

        if len(self.closes) >= 20:
            old_fast = sum(list(self.closes)[-5:]) / 5.0
            old_slow = sum(self.closes) / 20.0

        self.closes.append(close)

        if len(self.closes) < 20:
            return

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            old_fast is not None
            and old_slow is not None
            and old_fast <= old_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and self._time(9, 45) <= bar_end.time() <= self._time(14, 30)
        ):
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return

        if self.held_option is not None or self.entry_ticket is not None:
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped entry: no expiration satisfies the 7-day rule.")
            return

        selected_expiry = expiries[0]
        spy_price = float(self.Securities[self.spy].Price)
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug(
                "Skipped entry: no qualifying call at expiration {0}.".format(
                    selected_expiry
                )
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

    def _record_entry_fill(self, order_event: OrderEvent):
        quantity = abs(order_event.FillQuantity)
        if quantity <= 0:
            return

        self.entry_fill_value += quantity * order_event.FillPrice
        self.entry_filled_quantity += quantity
        self.entry_fill_price = (
            self.entry_fill_value / self.entry_filled_quantity
        )
        self.held_option = order_event.Symbol
        self.held_expiry = order_event.Symbol.ID.Date.date()

    def _submit_exit(self, tag):
        if self.held_option is None:
            return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=tag
        )
        self.Debug("Submitted exit for {0}: {1}".format(self.held_option, tag))

    def _current_option_contract(self, slice: Slice, symbol: Symbol):
        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return None

        for contract in chain:
            if contract.Symbol == symbol:
                return contract

        return None

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    @staticmethod
    def _bucket_end(end):
        minute = end.minute
        ceiling = ((minute + 4) // 5) * 5
        if ceiling == 60:
            return end.replace(
                hour=end.hour + 1,
                minute=0,
                second=0,
                microsecond=0
            )
        return end.replace(minute=ceiling, second=0, microsecond=0)

    @staticmethod
    def _is_complete_five_minute_bar(minutes, bucket_end):
        if len(minutes) != 5:
            return False

        expected_start = bucket_end - timedelta(minutes=4)
        for index, (timestamp, _) in enumerate(minutes):
            if timestamp != expected_start + timedelta(minutes=index):
                return False

        return True

    @staticmethod
    def _time(hour, minute):
        return __import__("datetime").time(hour, minute)

